extends Node3D
# Short-lived visual effects: tracers, goo puffs, bursts, damage numbers, Gatlion's roar wave.

func _fade_free(n: Node3D, dur: float, grow := 1.0) -> void:
	var tw := n.create_tween()
	tw.tween_property(n, "scale", n.scale * grow, dur)
	tw.tween_callback(n.queue_free)

func tracer(a: Vector3, b: Vector3, c: Color, w := 0.025) -> void:
	var dist := a.distance_to(b)
	if dist < 0.1:
		return
	var n := Node3D.new()
	add_child(n)
	n.global_position = (a + b) * 0.5
	n.look_at(b, Vector3.UP if absf((b - a).normalized().y) < 0.99 else Vector3.RIGHT)
	G.part(n, G.box(Vector3(1, 1, 1)), G.flat(c), Vector3.ZERO, Vector3(w, w, dist))
	_fade_free(n, 0.06, 0.2)

func puff(at: Vector3, c: Color, count := 3) -> void:
	var m := G.mat(c, 0.6)
	for i in count:
		var s := G.part(self, G.sphere(0.12, 6), m, at)
		var d := Vector3(G.rng.randf_range(-1, 1), G.rng.randf_range(-0.2, 1.2), G.rng.randf_range(-1, 1)) * 0.7
		var tw := s.create_tween().set_parallel()
		tw.tween_property(s, "position", at + d, 0.3).set_ease(Tween.EASE_OUT)
		tw.tween_property(s, "scale", Vector3.ONE * 0.05, 0.3)
		tw.chain().tween_callback(s.queue_free)

func burst(at: Vector3, c: Color, size := 1.0) -> void:
	var ball := G.part(self, G.sphere(0.5, 14), G.flat(Color(c.r, c.g, c.b, 0.55)), at, Vector3.ONE * 0.3 * size)
	var tw := ball.create_tween().set_parallel()
	tw.tween_property(ball, "scale", Vector3.ONE * 3.0 * size, 0.35).set_ease(Tween.EASE_OUT)
	tw.tween_property(ball, "transparency", 1.0, 0.35)
	tw.chain().tween_callback(ball.queue_free)
	var m := G.mat(c, 0.4, true)
	for i in int(8 * minf(size, 2.0)):
		var s := G.part(self, G.sphere(0.2 * size, 8), m, at)
		var d := Vector3(G.rng.randf_range(-1, 1), G.rng.randf_range(0.2, 1.5), G.rng.randf_range(-1, 1)) * 1.8 * size
		var t2 := s.create_tween().set_parallel()
		t2.tween_property(s, "position", at + d, 0.5).set_ease(Tween.EASE_OUT).set_trans(Tween.TRANS_QUAD)
		t2.tween_property(s, "scale", Vector3.ONE * 0.1, 0.5).set_ease(Tween.EASE_IN)
		t2.chain().tween_callback(s.queue_free)

func number(at: Vector3, n: float) -> void:
	var l := Label3D.new()
	l.text = str(int(round(n)))
	l.font = G.font_title
	l.font_size = 48
	l.pixel_size = 0.008
	l.outline_size = 12
	l.modulate = Color(1, 0.95, 0.4) if n < 30 else Color(1, 0.45, 0.3)
	l.outline_modulate = Color(0.15, 0.02, 0.1)
	l.billboard = BaseMaterial3D.BILLBOARD_ENABLED
	l.no_depth_test = true
	add_child(l)
	l.global_position = at + Vector3(G.rng.randf_range(-0.3, 0.3), 0.3, G.rng.randf_range(-0.3, 0.3))
	var tw := l.create_tween().set_parallel()
	tw.tween_property(l, "position", l.position + Vector3(0, 1.0, 0), 0.6)
	tw.tween_property(l, "modulate:a", 0.0, 0.6).set_delay(0.2)
	tw.chain().tween_callback(l.queue_free)

func roar(at: Vector3, fwd: Vector3) -> void:
	for i in 3:
		var ring := G.part(self, G.torus(0.3, 0.5), G.flat(Color(1.0, 0.7, 0.2, 0.7)), at + fwd * (0.5 + i * 0.4))
		ring.look_at(ring.global_position + fwd, Vector3.UP if absf(fwd.y) < 0.99 else Vector3.RIGHT)
		ring.rotate_object_local(Vector3.RIGHT, PI / 2)
		var tw := ring.create_tween().set_parallel()
		tw.tween_property(ring, "global_position", at + fwd * (6.0 + i * 3.0), 0.45).set_delay(i * 0.06)
		tw.tween_property(ring, "scale", Vector3.ONE * (8.0 + i * 3.0), 0.45).set_delay(i * 0.06)
		tw.tween_property(ring, "transparency", 1.0, 0.45).set_delay(i * 0.06)
		tw.chain().tween_callback(ring.queue_free)

