extends Node
# Global helpers: input map, materials + meshes, sound effects, music, voice-line data. Autoloaded as "G".

const LAYER_WORLD := 1
const LAYER_PLAYER := 2
const LAYER_ENEMY := 4

var headless := false
var selftest := false
var autoplay := false  # --autoplay: start at once and never pause (for screenshots)
var warp := -1         # --warp=N: start next to area N
var touch_mode := false
var rng := RandomNumberGenerator.new()
var lines := {}
var mouse_sens := 0.0024

var font_title: FontFile
var font_body: FontFile

var _mats := {}
var _meshes := {}
var _sfx := {}
var _players: Array[AudioStreamPlayer] = []
var _pidx := 0
var _music: AudioStreamPlayer
var _music_name := ""
var _music_target := 0.0

func _ready() -> void:
	headless = DisplayServer.get_name() == "headless"
	var args := OS.get_cmdline_user_args()
	selftest = "--selftest" in args
	for a in args:
		if a.begins_with("--screen="):
			var v := a.substr(9)
			autoplay = v.begins_with("auto")
			if v.begins_with("warp"):
				autoplay = true
				warp = int(v.substr(4))
	rng.randomize()
	if selftest:
		get_tree().create_timer(400.0, true, false, true).timeout.connect(func():
			print("SELFTEST FAIL: watchdog")
			get_tree().quit(2))
	_setup_input()
	font_title = load("res://assets/fonts/luckiest.woff2")
	font_body = load("res://assets/fonts/fredoka.woff2")
	var f := FileAccess.open("res://assets/voice/lines.json", FileAccess.READ)
	if f:
		lines = JSON.parse_string(f.get_as_text())
	for i in 14:
		var p := AudioStreamPlayer.new()
		add_child(p)
		_players.append(p)
	_music = AudioStreamPlayer.new()
	_music.volume_db = -80
	add_child(_music)

func _process(delta: float) -> void:
	if _music.playing:
		var cur := db_to_linear(_music.volume_db)
		cur = move_toward(cur, _music_target, delta * 0.6)
		_music.volume_db = linear_to_db(maxf(cur, 0.0001))
		if cur <= 0.0002 and _music_target == 0.0:
			_music.stop()

# ---------------- input ----------------
func _key(action: String, keys: Array, mouse := -1) -> void:
	if not InputMap.has_action(action):
		InputMap.add_action(action, 0.3)
	for k in keys:
		var e := InputEventKey.new()
		e.physical_keycode = k
		InputMap.action_add_event(action, e)
	if mouse >= 0:
		var m := InputEventMouseButton.new()
		m.button_index = mouse
		InputMap.action_add_event(action, m)

func _setup_input() -> void:
	_key("fwd", [KEY_W, KEY_UP])
	_key("back", [KEY_S, KEY_DOWN])
	_key("left", [KEY_A, KEY_LEFT])
	_key("right", [KEY_D, KEY_RIGHT])
	_key("jump", [KEY_SPACE])
	_key("dash", [KEY_SHIFT])
	_key("fire", [KEY_J], MOUSE_BUTTON_LEFT)
	_key("alt", [KEY_F, KEY_K], MOUSE_BUTTON_RIGHT)
	_key("swap", [KEY_Q, KEY_E, KEY_TAB])
	_key("gun1", [KEY_1])
	_key("gun2", [KEY_2])
	_key("reload", [KEY_R])
	_key("skip", [KEY_ENTER, KEY_KP_ENTER])

# ---------------- materials + meshes ----------------
func mat(c: Color, glow := 0.0, outline := false) -> StandardMaterial3D:
	var key := "%s|%s|%s" % [c.to_html(), glow, outline]
	if _mats.has(key):
		return _mats[key]
	var m := StandardMaterial3D.new()
	m.albedo_color = c
	m.diffuse_mode = BaseMaterial3D.DIFFUSE_TOON
	m.specular_mode = BaseMaterial3D.SPECULAR_TOON
	m.roughness = 0.55
	m.rim_enabled = true
	m.rim = 0.45
	m.rim_tint = 0.3
	if c.a < 1.0:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	if glow > 0.0:
		m.emission_enabled = true
		m.emission = c
		m.emission_energy_multiplier = glow
	if outline:
		var o := StandardMaterial3D.new()
		o.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
		o.albedo_color = Color(0.1, 0.03, 0.15)
		o.cull_mode = BaseMaterial3D.CULL_FRONT
		o.grow = true
		o.grow_amount = 0.025
		m.next_pass = o
	_mats[key] = m
	return m

func flat(c: Color) -> StandardMaterial3D:
	var key := "flat|" + c.to_html()
	if _mats.has(key):
		return _mats[key]
	var m := StandardMaterial3D.new()
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	m.albedo_color = c
	if c.a < 1.0:
		m.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
		m.cull_mode = BaseMaterial3D.CULL_DISABLED
	_mats[key] = m
	return m

func sphere(r := 0.5, seg := 16) -> SphereMesh:
	var key := "s%s_%s" % [r, seg]
	if not _meshes.has(key):
		var m := SphereMesh.new()
		m.radius = r
		m.height = r * 2.0
		m.radial_segments = seg
		m.rings = seg / 2
		_meshes[key] = m
	return _meshes[key]

func box(s: Vector3) -> BoxMesh:
	var key := "b%s" % s
	if not _meshes.has(key):
		var m := BoxMesh.new()
		m.size = s
		_meshes[key] = m
	return _meshes[key]

func cyl(top: float, bottom: float, h: float, seg := 12) -> CylinderMesh:
	var key := "c%s_%s_%s_%s" % [top, bottom, h, seg]
	if not _meshes.has(key):
		var m := CylinderMesh.new()
		m.top_radius = top
		m.bottom_radius = bottom
		m.height = h
		m.radial_segments = seg
		m.rings = 1
		_meshes[key] = m
	return _meshes[key]

func torus(inner: float, outer: float) -> TorusMesh:
	var key := "t%s_%s" % [inner, outer]
	if not _meshes.has(key):
		var m := TorusMesh.new()
		m.inner_radius = inner
		m.outer_radius = outer
		m.rings = 24
		m.ring_segments = 8
		_meshes[key] = m
	return _meshes[key]

func part(parent: Node, mesh: Mesh, material: Material, pos := Vector3.ZERO, scl := Vector3.ONE, rot := Vector3.ZERO) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = material
	mi.position = pos
	mi.scale = scl
	mi.rotation = rot
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	parent.add_child(mi)
	return mi

# Googly eye: white ball + dark pupil pointing along local -Z. Returns the pupil so it can be moved.
func eye(parent: Node3D, pos: Vector3, r: float) -> MeshInstance3D:
	var white := part(parent, sphere(r, 12), flat(Color(1, 1, 1)), pos)
	var pupil := part(white, sphere(r * 0.5, 10), flat(Color(0.08, 0.02, 0.1)), Vector3(0, 0, -r * 0.62))
	return pupil

# ---------------- audio ----------------
func sfx(name: String, vol := 0.0, pitch := 1.0) -> void:
	if headless:
		return
	if not _sfx.has(name):
		_sfx[name] = load("res://assets/sfx/%s.wav" % name)
	var p := _players[_pidx]
	_pidx = (_pidx + 1) % _players.size()
	p.stream = _sfx[name]
	p.volume_db = vol
	p.pitch_scale = pitch * rng.randf_range(0.95, 1.05)
	p.play()

func sfx3d(name: String, at: Vector3, parent: Node, vol := 0.0) -> void:
	if headless:
		return
	if not _sfx.has(name):
		_sfx[name] = load("res://assets/sfx/%s.wav" % name)
	var p := AudioStreamPlayer3D.new()
	p.stream = _sfx[name]
	p.volume_db = vol
	p.unit_size = 8.0
	p.pitch_scale = rng.randf_range(0.92, 1.08)
	parent.add_child(p)
	p.global_position = at
	p.play()
	p.finished.connect(p.queue_free)

func music(name: String) -> void:
	if headless or name == _music_name:
		return
	_music_name = name
	var s: AudioStreamOggVorbis = load("res://assets/sfx/%s.ogg" % name)
	s.loop = true
	_music.stream = s
	_music.volume_db = -30
	_music_target = 0.32
	_music.play()

func music_stop() -> void:
	_music_name = ""
	_music_target = 0.0

func voice_stream(id: String) -> AudioStream:
	return load("res://assets/voice/%s.ogg" % id)

func line(id: String) -> Dictionary:
	return lines.get(id, {"who": "?", "text": id, "dur": 1.0, "env": "5"})

# Mouth openness 0..1 for line `id` at time `t` seconds.
func mouth_at(id: String, t: float) -> float:
	var env: String = line(id).env
	var i := int(t * 20.0)
	if i < 0 or i >= env.length():
		return 0.0
	return float(env.unicode_at(i) - 48) / 9.0

func pick(a: Array) -> Variant:
	return a[rng.randi() % a.size()]

const SPEAKER_COLOR := {
	"GATLION": Color(1.0, 0.72, 0.18), "SQUIBBY": Color(0.3, 1.0, 0.75), "ZIB": Color(0.75, 0.6, 1.0),
	"GRUBBO": Color(0.55, 1.0, 0.3), "SPITZER": Color(0.9, 0.45, 1.0), "BONKHEAD": Color(1.0, 0.5, 0.25),
	"GLORP": Color(1.0, 0.35, 0.55),
}

files.scripts/talk.gd:
extends Node
# Dialogue: one spoken line at a time with priorities, subtitles and mouth data. Autoloaded as "Talk".
# Priority: 3 = story (never dropped), 2 = important, 1 = chatter (dropped when busy or too soon).
# Timing uses each line's duration from lines.json, so it also works headless.

signal started(id: String, who: String, text: String, dur: float)
signal ended(id: String)

var cur_id := ""
var cur_who := ""
var cur_prio := 0
var cur_t := 0.0
var cur_dur := 0.0
var queue: Array = []  # [{id, prio, gap}]
var last_chatter := -100.0
var gap := 0.0
var clock := 0.0
var player: AudioStreamPlayer

func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	player = AudioStreamPlayer.new()
	player.volume_db = 2.0
	add_child(player)

func busy() -> bool:
	return cur_id != "" or not queue.is_empty()

func story_busy() -> bool:
	if cur_prio >= 3:
		return true
	for q in queue:
		if q.prio >= 3:
			return true
	return false

func say(id: String, prio := 2) -> void:
	if not G.lines.has(id):
		push_warning("missing line " + id)
		return
	if prio <= 1:
		if busy() or clock - last_chatter < 5.0:
			return
		last_chatter = clock
	if cur_id != "" and prio > cur_prio and cur_prio <= 1:
		_finish()
	queue.append({"id": id, "prio": prio})
	if cur_id == "" and gap <= 0.0:
		_next()

func seq(ids: Array, prio := 2) -> void:
	for id in ids:
		say(id, prio)

func chatter(ids: Array, chance := 1.0) -> void:
	if G.rng.randf() <= chance:
		say(G.pick(ids), 1)

func clear() -> void:
	queue.clear()
	if cur_id != "":
		_finish()

func skip_story() -> void:
	queue = queue.filter(func(q): return q.prio < 3)
	if cur_prio >= 3:
		_finish()

func mouth(who: String) -> float:
	if cur_who != who:
		return 0.0
	return G.mouth_at(cur_id, cur_t)

func _next() -> void:
	if queue.is_empty():
		return
	var q: Dictionary = queue.pop_front()
	var l := G.line(q.id)
	cur_id = q.id
	cur_who = l.who
	cur_prio = q.prio
	cur_t = 0.0
	cur_dur = float(l.dur)
	if not G.headless:
		player.stream = G.voice_stream(cur_id)
		player.play()
	started.emit(cur_id, cur_who, l.text, cur_dur)

func _finish() -> void:
	var id := cur_id
	player.stop()
	cur_id = ""
	cur_who = ""
	cur_prio = 0
	gap = 0.25
	ended.emit(id)

func _process(delta: float) -> void:
	player.stream_paused = get_tree().paused
	if get_tree().paused:
		return
	clock += delta
	if cur_id != "":
		cur_t += delta
		if cur_t >= cur_dur + 0.15:
			_finish()
	elif gap > 0.0:
		gap -= delta
		if gap <= 0.0:
			_next()
	elif not queue.is_empty():
		_next()
